    #[test]
    fn test_backspaces() {
        let input: Vec<char> = "01B0B1".chars().collect();
        // Process: "0" -> "01" -> pop -> "0" -> "00" -> pop -> "0" -> "01"
        assert_eq!(solve(input), "01".chars().collect::<Vec<char>>());
    }

    #[test]
    fn test_leading_backspaces() {
        let input: Vec<char> = "BBB01".chars().collect();
        // Leading Bs do nothing, result is "01"
        assert_eq!(solve(input), "01".chars().collect::<Vec<char>>());
    }

    #[test]
    fn test_mixed() {
        let input: Vec<char> = "1B0B1B0".chars().collect();
        // "1" -> pop -> "" -> "0" -> pop -> "" -> "1" -> pop -> "" -> "0"
        assert_eq!(solve(input), "0".chars().collect::<Vec<char>>());
    }
